const root=document.querySelector('#app');
const pages={beranda:'Beranda',mengenal:'Mengenal SB',kamus:'Kamus Biaya',regulasi:'Regulasi',dashboard:'Dashboard',pustaka:'Pustaka',indeks:'Indeks KMK',faq:'FAQ'};
const icon=(name,size=20)=>{const paths={search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',book:'<path d="M4 19V5a2 2 0 0 1 2-2h13v16H6a2 2 0 0 0 0 4h13"/>',shield:'<path d="m12 2 8 4v6c0 5-3 8-8 10-5-2-8-5-8-10V6l8-4Z"/><path d="m9 12 2 2 4-4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M9 4H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h4m6-4 4-4-4-4m-9 4h13"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8L3 5Z"/>',chart:'<path d="M3 3v18h18M7 16l4-4 4 2 5-7"/>',file:'<path d="M6 2h8l5 5v15H6zM14 2v6h5M9 13h7m-7 4h7"/>',eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 4m0 3h.01"/>',home:'<path d="M3 11 12 3l9 8"/><path d="M5 10v10h14V10"/><path d="M10 20v-6h4v6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 13 9 5 9-5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>'};return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.book}</svg>`;};
// Regulasi pilihan: data referensi disajikan tanpa bergantung pada publikasi D1.
// Data besaran per item tetap harus disinkronkan melalui Google Sheets resmi.
const FEATURED_REGULATIONS = [
 {id:'REF-PMK-54-2026',kelompok:'SBM 2027',jenis:'PMK',nomor:'54',tahun:2026,judul:'Standar Biaya Masukan',deskripsi:'Mengatur kategori SBM serta biaya batas tertinggi dan dapat dilampaui; digunakan untuk penyusunan RKA mulai TA 2027. Rincian besaran pada KMK 296/2026.',url:'/regulasi/pmk-54-2026.pdf',status_verifikasi:'PDF tersedia',sumber:'PMK 54/2026 · 12 halaman'},
 {id:'REF-KMK-296-2026',kelompok:'SBM 2027',jenis:'KMK',nomor:'296',tahun:2026,judul:'Rincian Besaran Standar Biaya Masukan',deskripsi:'Ditetapkan 25 September 2026. Berlaku mulai TA 2027. Lampiran I: batas tertinggi; Lampiran II: dapat dilampaui, beserta penjelasannya.',url:'/regulasi/kmk-296-2026.pdf',status_verifikasi:'Naskah PDF diunggah pengelola',sumber:'KMK 296/2026, 126 halaman'},
 {id:'REF-PMK-79-2025',kelompok:'SSB',jenis:'PMK',nomor:'79',tahun:2025,judul:'Standar Struktur Biaya dalam Penganggaran Kementerian Negara/Lembaga',deskripsi:'Standar Struktur Biaya dalam penganggaran K/L; persentase biaya pendukung menurut Grup KRO dan prosedur permintaan pelampauan.',url:'/regulasi/pmk-79-2025.pdf',status_verifikasi:'PDF tersedia',sumber:'PMK 79/2025 · 7 halaman'},
 {id:'REF-PMK-3-2026',kelompok:'SBK 2027',jenis:'PMK',nomor:'3',tahun:2026,judul:'Standar Biaya Keluaran dalam Penganggaran Kementerian Negara/Lembaga',deskripsi:'Menetapkan kategori SBK umum dan khusus beserta uraian; penggunaan untuk RKA-K/L mulai 2026. Rincian indeks terdapat dalam KMK 57/2026.',url:'/regulasi/pmk-3-2026.pdf',status_verifikasi:'PDF tersedia',sumber:'PMK 3/2026 · 154 halaman'},
 {id:'REF-KMK-57-2026',kelompok:'SBK 2027',jenis:'KMK',nomor:'57',tahun:2026,judul:'Rincian Indeks Standar Biaya Keluaran dalam Penganggaran Kementerian Negara/Lembaga',deskripsi:'Ditetapkan 24 Februari 2026. Digunakan untuk penyusunan RKA-K/L mulai 2026 (bukan khusus TA 2027). Lampiran I: SBK umum; Lampiran II: SBK khusus.',url:'/regulasi/kmk-57-2026.pdf',status_verifikasi:'Naskah PDF diunggah pengelola',sumber:'KMK 57/2026, 177 halaman'}
];
const pageIcons={beranda:'home',mengenal:'info',kamus:'book',regulasi:'file',dashboard:'chart',pustaka:'layers',indeks:'grid',faq:'help'};
const pageIcon=()=>`<span class="page-icon" aria-hidden="true">${icon(pageIcons[state.page],30)}</span>`;
const verifiedLink=(url)=>typeof url==='string' && (/^https:\/\//.test(url)||/^\/regulasi\/[a-z0-9-]+\.pdf$/.test(url));
const state={page:'beranda',search:'',jenis:'',kelompok:'',kamusTab:'istilah',docSearch:'',docKind:'',data:[],summary:null,regs:[],docs:[],faq:[],loading:true,error:'',selected:null};
const escapeHTML=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const niceDate=(d)=>{if(!d)return '—';const x=new Date(d);return isNaN(x)?String(d):new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(x)};
const badge=(s)=>{const k=String(s??'').trim().split(/\s+/)[0].toLowerCase();return `<span class="pill${/^(sbm|sbk|ssb|pmk|kmk)$/.test(k)?' k-'+k:''}">${escapeHTML(s)}</span>`;};
async function load(){state.loading=true;render();try{const endpoints=['summary','items?limit=500','regulations?limit=500','documents?limit=500','faq?limit=500'];const responses=await Promise.all(endpoints.map(x=>fetch('/api/'+x,{credentials:'same-origin',cache:'no-store'})));if(responses.some(x=>x.status===401)){location.href='/login';return;}if(responses.some(x=>!x.ok))throw Error('Gagal membaca data portal');const [summary,items,regs,docs,faq]=await Promise.all(responses.map(x=>x.json()));state.summary=summary.data||null;state.data=items.data||[];state.regs=regs.data||[];state.docs=docs.data||[];state.faq=faq.data||[];state.error='';}catch(e){state.error=e.message||'Tidak dapat memuat data. Coba muat ulang halaman.';}state.loading=false;render();}
const menu=()=>Object.entries(pages).map(([id,label])=>`<button class="nav-link ${state.page===id?'active':''}" data-page="${id}">${icon(pageIcons[id],15)}${label}</button>`).join('');
const stat=(value,title,ic)=>`<article class="stat"><span class="stat-icon">${icon(ic,22)}</span><div><strong>${escapeHTML(value)}</strong><small>${title}</small></div></article>`;
const typeCards=()=>[['SBM','Standar Biaya Masukan','Acuan biaya komponen masukan dan pelaksanaan kegiatan.','sbm.svg'],['SBK','Standar Biaya Keluaran','Pendekatan biaya per keluaran atau hasil kegiatan.','sbk.svg'],['SSB','Standar Struktur Biaya','Informasi struktur dan komposisi biaya.','ssb.svg']].map(([k,t,desc,img])=>`<article class="type-card kind-${k.toLowerCase()}"><img src="/icons/${img}" alt="Ikon ${k}"/><span>${k}</span><h3>${t}</h3><p>${desc}</p><button class="text-button" data-kind="${k}">Lihat istilah ${icon('arrow',16)}</button></article>`).join('');
const home=()=>`<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> PUSAT INFORMASI STANDAR BIAYA</div><h1>Memahami Standar Biaya,<br><em>Lebih Mudah.</em></h1><p>Temukan definisi, jenis, item, besaran, regulasi, dan referensi standar biaya dalam satu portal yang terstruktur.</p><form id="hero-search" class="search-box">${icon('search',21)}<input name="q" placeholder="Cari honorarium, perjalanan dinas, SBM, regulasi..." aria-label="Cari standar biaya"/><button type="submit">Cari Sekarang ${icon('arrow',17)}</button></form><div class="quick">Penelusuran cepat: <button data-search="Honorarium">Honorarium</button><button data-search="Perjalanan Dinas">Perjalanan Dinas</button><button data-kind="SBK">Standar Biaya Keluaran</button></div></div><div class="hero-art" aria-hidden="true"><div class="halo"></div><img class="hero-core" src="/icons/portal-logo.svg"/><img class="orbit a" src="/icons/sbm.svg"/><img class="orbit b" src="/icons/sbk.svg"/><img class="orbit c" src="/icons/ssb.svg"/><div class="art-label">STANDAR<br>BIAYA</div></div></section><section class="stats">${stat(state.summary?.itemCount??'—','Item Standar Biaya','book')}${stat(state.summary?.regulationCount??'—','Referensi Regulasi','file')}${stat(state.summary?.documentCount??'—','Dokumen Pustaka','shield')}${stat(niceDate(state.summary?.updatedAt),'Terakhir Diperbarui','calendar')}</section><section class="section-heading"><div><span class="small-label">JELAJAHI KATALOG</span><h2>Jenis Standar Biaya</h2><p>Pilih kategori untuk mulai menjelajahi referensi dan ketentuannya.</p></div><button class="secondary" data-page="kamus">Buka Kamus ${icon('arrow',17)}</button></section><section class="types">${typeCards()}</section>`;
const cards=(items,kind)=>items.map(x=>`<article class="entry"><div class="entry-head">${badge(x.jenis||x.kategori||x.status||kind)}<small>${escapeHTML(x.tahun||x.nomor||'')}</small></div><h3>${escapeHTML(x.nama||x.judul||x.pertanyaan||'Tidak ada judul')}</h3><p>${escapeHTML(x.definisi||x.deskripsi||x.jawaban||x.kelompok||'')}</p><div class="entry-foot">${x.satuan?`<span>Satuan: ${escapeHTML(x.satuan)}</span>`:''}${x.id&&kind==='Item'?`<button class="text-button" data-detail="${escapeHTML(x.id)}">Detail ${icon('arrow',15)}</button>`:''}${x.url&&/^https:\/\//.test(x.url)?`<a href="${escapeHTML(x.url)}" target="_blank" rel="noopener noreferrer">Lihat regulasi ↗</a>`:''}</div></article>`).join('');
const filtered=()=>state.data.filter(x=>(!state.jenis||x.jenis===state.jenis)&&(!state.search||JSON.stringify([x.nama,x.kelompok,x.subkelompok,x.definisi,x.jenis]).toLowerCase().includes(state.search.toLowerCase())));
// Kamus: tab Istilah (public/data/istilah.json, dari PMK/KMK) dan tab Item Biaya (D1).
let istilahData=null,istilahError='';
async function loadIstilah(){if(istilahData||istilahError)return;try{const r=await fetch('/data/istilah.json',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error();istilahData=(await r.json()).istilah||[];}catch(e){istilahError='Daftar istilah belum dapat dimuat. Coba muat ulang halaman.';}if(state.page==='kamus')render();}
const KELOMPOK_URUT=['Ketentuan Umum','Honorarium','Fasilitas','Perjalanan Dinas','Pemeliharaan','Barang dan Jasa','Bantuan','Klasifikasi Biaya','Batas Biaya Pendukung per Grup KRO','Ketentuan Umum SBK Umum','SBK Umum'];
const pdfLink=(url)=>typeof url==='string'&&/^\/regulasi\/[a-z0-9-]+\.pdf(#page=\d+)?$/.test(url)?url:'';
const istilahMatch=(x)=>(!state.jenis||x.jenis===state.jenis)&&(!state.kelompok||x.kelompok===state.kelompok)&&(!state.search||[x.istilah,x.definisi,x.kelompok,x.sumber].join(' ').toLowerCase().includes(state.search.toLowerCase()));
const istilahCard=(x)=>{const url=pdfLink(x.url);return `<article class="term-card term-${x.jenis.toLowerCase()}"><div class="entry-head">${badge(x.jenis)}<small>${escapeHTML(x.kelompok)}</small></div><h3>${escapeHTML(x.istilah)}</h3><p>${escapeHTML(x.definisi)}</p><div class="term-foot"><span>${icon('file',14)} ${escapeHTML(x.sumber)}</span>${url?`<a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">Lihat di PDF ↗</a>`:''}</div></article>`;};
function istilahView(){if(istilahError)return `<div class="empty">${escapeHTML(istilahError)}</div>`;if(!istilahData){loadIstilah();return '<div class="loading">Memuat daftar istilah...</div>';}
const pool=istilahData.filter(x=>!state.jenis||x.jenis===state.jenis);const groups=[...new Set(pool.map(x=>x.kelompok))].sort((a,b)=>KELOMPOK_URUT.indexOf(a)-KELOMPOK_URUT.indexOf(b));
const list=istilahData.filter(istilahMatch);const byGroup=groups.map(g=>[g,list.filter(x=>x.kelompok===g)]).filter(([,xs])=>xs.length);
const sumber={'':'PMK 54/2026 · KMK 296/2026 · PMK 3/2026 · KMK 57/2026 · PMK 79/2025',SBM:'PMK 54/2026 dan KMK 296/2026',SBK:'PMK 3/2026 dan KMK 57/2026',SSB:'PMK 79/2025'}[state.jenis];
return `${state.jenis&&groups.length>1?`<div class="chips">${['',...groups].map(g=>`<button class="chip ${state.kelompok===g?'active':''}" data-kelompok="${escapeHTML(g)}">${g?escapeHTML(g):'Semua kelompok'}<span>${g?pool.filter(x=>x.kelompok===g).length:pool.length}</span></button>`).join('')}</div>`:''}<div class="result-note">Menampilkan ${list.length} istilah · Sumber: ${sumber}. Definisi disalin dari teks peraturan; rumusan resmi tetap mengacu pada PDF.</div>${byGroup.length?byGroup.map(([g,xs])=>`<section class="term-group"><h2>${escapeHTML(g)} <span>${xs.length}</span></h2><div class="term-list">${xs.map(istilahCard).join('')}</div></section>`).join(''):'<div class="empty">Tidak ada istilah yang cocok. Coba kata lain atau pilih "Semua jenis".</div>'}`;}
const catalog=()=>`<section class="page-head">${pageIcon()}<span class="small-label">PUSAT INFORMASI STANDAR BIAYA</span><h1>Jelajahi Kamus Biaya</h1><p>Istilah resmi dari peraturan standar biaya, serta item biaya yang tersedia dalam database portal.</p></section><div class="kamus-tabs" role="tablist">${[['istilah','Istilah',istilahData?istilahData.length:''],['item','Item Biaya',state.data.length]].map(([k,l,n])=>`<button role="tab" aria-selected="${state.kamusTab===k}" class="kamus-tab ${state.kamusTab===k?'active':''}" data-kamustab="${k}">${l}${n!==''?`<span>${n}</span>`:''}</button>`).join('')}</div><div class="toolbar"><label class="filter-search">${icon('search',20)}<input id="catalog-search" placeholder="${state.kamusTab==='istilah'?'Cari istilah atau definisi, misalnya: narasumber, RO, biaya pendukung...':'Cari nama, kelompok, definisi...'}" value="${escapeHTML(state.search)}" /></label><label class="kind-select">${icon('filter',18)}<select id="catalog-kind"><option value="">Semua jenis</option>${['SBM','SBK','SSB'].map(t=>`<option value="${t}" ${state.jenis===t?'selected':''}>${t}</option>`).join('')}</select></label></div>${state.kamusTab==='istilah'?istilahView():`<div class="result-note">Menampilkan ${filtered().length} item dari katalog yang dimuat.</div><div class="entries">${filtered().length?cards(filtered(),'Item'):'<div class="empty">Belum ada item yang cocok dengan pencarian.</div>'}</div>${state.data.length>=500?'<p class="result-note">Katalog awal dibatasi 500 item. Gunakan pencarian server-side untuk katalog yang lebih besar.</p>':''}`}`;
const simple=(key,title,subtitle,items)=>`<section class="page-head">${pageIcon()}<span class="small-label">PORTAL STANDAR BIAYA</span><h1>${title}</h1><p>${subtitle}</p></section><div class="entries">${items.length?cards(items,key):'<div class="empty">Belum ada data yang dipublikasikan untuk bagian ini.</div>'}</div>`;
// Pencarian teks dari 5 dokumen PDF; hasil adalah referensi halaman, bukan data D1.
let kmkIndex=null;
const kmkSearchUI=()=>`<section class="reg-group kmk-search"><div class="reg-group-title"><h2>Cari teks dalam PMK & KMK</h2><span>5 dokumen</span></div><p>Temukan kata, nomenklatur, dan besaran dalam kelima PDF. Hasil membuka halaman dokumen asli untuk pemeriksaan.</p><form id="kmk-search-form" class="toolbar"><label class="filter-search">${icon('search',20)}<input id="kmk-query" placeholder="Contoh: honorarium moderator, layanan audit, uang makan" required minlength="2" /></label><select id="kmk-doc" aria-label="Dokumen yang dicari"><option value="">Semua regulasi</option><option value="pmk54">PMK 54/2026</option><option value="kmk296">KMK 296/2026</option><option value="pmk79">PMK 79/2025</option><option value="pmk3">PMK 3/2026</option><option value="kmk57">KMK 57/2026</option></select><button type="submit" class="secondary">Cari lampiran</button></form><div id="kmk-results" class="kmk-results" aria-live="polite">Masukkan istilah untuk mencari teks kedua lampiran.</div></section>`;
function excerptAround(text,query){const low=text.toLocaleLowerCase('id-ID');let idx=low.indexOf(query);if(idx<0)idx=0;return (idx>65?'…':'')+text.slice(Math.max(0,idx-65),Math.min(text.length,idx+175))+(idx+175<text.length?'…':'');}
async function kmkLookup(ev){ev.preventDefault();const node=document.querySelector('#kmk-results');const query=document.querySelector('#kmk-query').value.trim().toLocaleLowerCase('id-ID');const pick=document.querySelector('#kmk-doc').value;if(query.length<2)return;node.textContent='Menelusuri PDF...';try{if(!kmkIndex){const res=await fetch('/regulasi/indeks-kmk.json',{credentials:'same-origin',cache:'no-store'});if(!res.ok)throw new Error('Indeks tidak dapat dimuat');kmkIndex=await res.json();}const matches=kmkIndex.pages.filter(p=>(!pick||p.doc===pick)&&p.text.toLocaleLowerCase('id-ID').includes(query));const shown=matches.slice(0,40);node.innerHTML=`<p class="result-note">${matches.length} halaman cocok. Menampilkan maksimal 40 halaman.</p>`+(shown.length?shown.map(p=>{const d=kmkIndex.documents.find(x=>x.id===p.doc);return `<article class="kmk-result"><b>${escapeHTML(d.label)} · halaman PDF ${p.page}</b><p>${escapeHTML(excerptAround(p.text,query))}</p><a href="${escapeHTML(d.url)}#page=${p.page}" target="_blank" rel="noopener noreferrer">Buka halaman ${p.page} di PDF ↗</a></article>`;}).join(''):'<p class="empty">Tidak ditemukan dalam teks ekstraksi PDF. Coba istilah yang lebih singkat atau buka PDF asli.</p>');}catch(e){node.textContent='Pencarian belum tersedia. Pastikan indeks PDF ikut terunggah ke Cloudflare.';}}
const regulationCatalog=()=>{
  const groups=['SBM 2027','SSB','SBK 2027'];
  const database=state.regs.filter(x=>!FEATURED_REGULATIONS.some(r=>String(r.jenis).toUpperCase()===String(x.jenis).toUpperCase()&&String(r.nomor)===String(x.nomor)&&Number(r.tahun)===Number(x.tahun)));
  const featured=groups.map(group=>`<section class="reg-group"><div class="reg-group-title"><h2>${escapeHTML(group)}</h2><span>${FEATURED_REGULATIONS.filter(x=>x.kelompok===group).length} referensi</span></div><div class="entries">${FEATURED_REGULATIONS.filter(x=>x.kelompok===group).map(r=>`<article class="entry regulation-entry"><div class="entry-head">${badge(r.jenis+' '+r.nomor+'/'+r.tahun)}<span class="verification ${r.status_verifikasi.startsWith('Terverifikasi')?'verified':'pending'}">${escapeHTML(r.status_verifikasi)}</span></div><h3>${escapeHTML(r.judul)}</h3><p>${escapeHTML(r.deskripsi)}</p><div class="entry-foot"><span>${escapeHTML(r.sumber)}</span>${verifiedLink(r.url)?`<a target="_blank" rel="noopener noreferrer" href="${escapeHTML(r.url)}">Baca PDF ↗</a>`:'<span>Dokumen resmi belum tersedia</span>'}</div></article>`).join('')}</div></section>`).join('');
  return `<section class="page-head">${pageIcon()}<span class="small-label">DASAR HUKUM STANDAR BIAYA</span><h1>Regulasi SBM, SBK & SSB</h1><p>Regulasi pilihan tahun anggaran 2027, lengkap dengan tautan sumber dan status verifikasi dokumen.</p></section><div class="reg-advisory">Kelima naskah PMK dan KMK dilengkapi PDF yang diunggah pengelola dan pencarian isi per halaman. KMK 296 berlaku untuk TA 2027, sementara KMK 57 digunakan untuk penyusunan RKA-K/L mulai 2026. Besaran lampiran belum diimpor otomatis ke D1; cek PDF sebelum digunakan.</div>${featured}${kmkSearchUI()}${database.length?`<section class="reg-group"><div class="reg-group-title"><h2>Regulasi dari Database</h2><span>${database.length} dokumen</span></div><div class="entries">${cards(database,'Regulasi')}</div></section>`:''}`;
};
const faq=()=>`<section class="page-head">${pageIcon()}<span class="small-label">PUSAT BANTUAN</span><h1>Pertanyaan yang Sering Diajukan</h1><p>Jawaban ringkas mengenai standar biaya dan penggunaan portal.</p></section><section class="faqs">${state.faq.length?state.faq.map((x,i)=>`<details ${i===0?'open':''}><summary>${escapeHTML(x.pertanyaan)}</summary><p>${escapeHTML(x.jawaban)}</p></details>`).join(''):'<div class="empty">Belum ada FAQ yang dipublikasikan.</div>'}</section>`;
// Mengenal SB: narasi dari PMK 54/2026, PMK 3/2026, PMK 79/2025 dan bahan paparan DJA.
const sbIcon=(paths,size=22)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths}</svg>`;
const SB_ICONS={
  coin:'<circle cx="12" cy="12" r="9"/><path d="M14.5 9.5c-.5-1-1.5-1.5-2.5-1.5-1.7 0-3 .9-3 2s1.3 1.6 3 1.9 3 .9 3 2.1-1.3 2-3 2c-1 0-2-.5-2.5-1.5M12 6v2m0 8v2"/>',
  star:'<path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1L3.2 9.5l6.1-.9z"/>',
  plane:'<path d="m22 2-7 20-4-9-9-4 20-7Z"/><path d="M22 2 11 13"/>',
  tool:'<path d="M14.7 6.3a4 4 0 0 0-5.4 5.4L3 18l3 3 6.3-6.3a4 4 0 0 0 5.4-5.4l-2.6 2.6-2.4-.6-.6-2.4z"/>',
  box:'<path d="m21 8-9-5-9 5 9 5 9-5Z"/><path d="M3 8v8l9 5 9-5V8M12 13v8"/>',
  gift:'<rect x="3" y="8" width="18" height="5" rx="1"/><path d="M5 13v8h14v-8M12 8v13M12 8C10 8 7 7.5 7.5 5S11 5 12 8Zm0 0c2 0 5-.5 4.5-3S13 5 12 8Z"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1.2"/>',
  pie:'<path d="M21 12A9 9 0 1 1 12 3v9z"/><path d="M15 3.3A9 9 0 0 1 20.7 9H15z"/>',
  users:'<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0M16 4.5a3.5 3.5 0 0 1 0 7M18 14.5a6.5 6.5 0 0 1 3.5 5.5"/>',
  check:'<path d="M20 6 9 17l-5-5"/>',
  up:'<path d="M7 17 17 7M9 7h8v8"/>',
  lock:'<rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',
  eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'
};
const sbi=(name,size)=>sbIcon(SB_ICONS[name],size);
const SB_TYPES=[
  {k:'sbm',kode:'SBM',nama:'Standar Biaya Masukan',img:'sbm.svg',ringkas:'Harga satuan untuk setiap masukan: honor, perjalanan dinas, konsumsi, sewa, dan lainnya.',dasar:'PMK 54/2026 · KMK 296/2026'},
  {k:'sbk',kode:'SBK',nama:'Standar Biaya Keluaran',img:'sbk.svg',ringkas:'Indeks biaya untuk menghasilkan satu volume keluaran (output) secara utuh.',dasar:'PMK 3/2026 · KMK 57/2026'},
  {k:'ssb',kode:'SSB',nama:'Standar Struktur Biaya',img:'ssb.svg',ringkas:'Batas komposisi biaya pendukung terhadap total biaya satu Rincian Output.',dasar:'PMK 79/2025'}
];
const sbFacts=(items)=>`<div class="sb-facts">${items.map(([v,l])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`;
const sbHead=(t,no)=>`<header class="sb-head"><img src="/icons/${t.img}" alt=""/><div><span class="sb-no">${no} · ${t.kode}</span><h2>${t.nama}</h2><p class="sb-law">${icon('file',15)} ${t.dasar}</p></div></header>`;
const intro=()=>{const [m,k,s]=SB_TYPES;return `<section class="page-head">${pageIcon()}<span class="small-label">PENGENALAN</span><h1>Mengenal Standar Biaya</h1><p>Apa itu standar biaya, mengapa ia penting, dan bagaimana SBM, SBK, dan SSB bekerja dalam penyusunan anggaran.</p></section>
<section class="sb-intro"><div class="sb-intro-text"><span class="small-label">APA ITU STANDAR BIAYA?</span><h2>Satu acuan harga untuk seluruh anggaran negara</h2><p><b>Standar Biaya</b> adalah satuan biaya yang ditetapkan oleh Menteri Keuangan selaku pengelola fiskal (<i>chief financial officer</i>), dan digunakan sebagai acuan perhitungan kebutuhan anggaran, baik saat menyusun RKA maupun saat melaksanakan anggaran.</p><p>Standar biaya ditetapkan dengan Peraturan Menteri Keuangan setelah berkoordinasi dengan kementerian/lembaga. Dengan satu acuan yang sama, biaya rapat di satu kementerian dihitung dengan cara yang sama di kementerian lain. Hasilnya, anggaran menjadi wajar, efisien, dan dapat dipertanggungjawabkan.</p><div class="sb-funds"><span>Berlaku untuk semua sumber dana</span>${['RM','PNBP','PHLN','BLU','SBSN'].map(x=>`<b>${x}</b>`).join('')}</div></div>
<div class="sb-pillars" aria-label="Kedudukan standar biaya dalam PP 6/2023"><p class="sb-pillars-title">PP 6/2023 · Penyusunan RKA-K/L</p><div class="sb-row"><span>Pendekatan</span><div><i>Kerangka Pengeluaran Jangka Menengah</i><i>Penganggaran Terpadu</i><i>Penganggaran Berbasis Kinerja</i></div></div><div class="sb-row"><span>Instrumen</span><div><i>Indikator Kinerja</i><i class="on">${sbi('star',14)} Standar Biaya</i><i>Evaluasi Kinerja</i></div></div><p class="sb-pillars-note">Standar biaya adalah salah satu dari tiga instrumen penganggaran berbasis kinerja.</p></div></section>
<section class="sb-roles">${[['users','Tanggung jawab PA/KPA','Pengguna Anggaran/Kuasa Pengguna Anggaran bertanggung jawab atas kesesuaian penggunaan serta kebenaran formil dan materiil standar biaya.'],['eye','Pengawasan APIP','Aparat pengawasan intern pemerintah K/L mengawasi penggunaan standar biaya sesuai kewenangannya.'],['target','Monev Kemenkeu','Kementerian Keuangan c.q. DJA bersama K/L memantau dan mengevaluasi penerapan standar biaya.']].map(([ic,t,d])=>`<article><span>${sbi(ic,20)}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</section>
<section class="section-heading"><div><span class="small-label">TIGA JENIS STANDAR BIAYA</span><h2>SBM, SBK, dan SSB</h2><p>Ketiganya saling melengkapi: dari harga satuan masukan, biaya per keluaran, hingga komposisi biaya.</p></div></section>
<nav class="sb-jump">${SB_TYPES.map((t,i)=>`<a href="#sb-${t.k}" class="sb-jump-${t.k}"><img src="/icons/${t.img}" alt=""/><span><small>0${i+1} · ${t.kode}</small><b>${t.nama}</b><em>${t.ringkas}</em></span></a>`).join('')}</nav>

<article class="sb-card sb-sbm" id="sb-sbm">${sbHead(m,'01')}
<p class="sb-lead"><b>SBM</b> adalah standar biaya yang digunakan sebagai <b>masukan (input)</b> untuk menyusun rincian biaya dalam suatu keluaran. Bayangkan SBM sebagai "daftar harga" resmi: berapa paling tinggi honor narasumber per jam, uang harian perjalanan dinas per provinsi, atau konsumsi rapat per orang.</p>
<h3 class="sb-sub">6 kelompok satuan biaya (Pasal 2 PMK 54/2026)</h3>
<div class="sb-chips">${[['coin','Honorarium'],['star','Fasilitas'],['plane','Perjalanan Dinas'],['tool','Pemeliharaan'],['box','Barang dan Jasa'],['gift','Bantuan']].map(([ic,t])=>`<span>${sbi(ic,18)}${t}</span>`).join('')}</div>
<div class="sb-split"><div class="sb-box"><span class="sb-tag">${sbi('lock',15)} Lampiran I</span><h4>Batas tertinggi</h4><p>Besaran biaya yang <b>tidak dapat dilampaui</b>, baik dalam perencanaan maupun pelaksanaan anggaran.</p></div><div class="sb-box"><span class="sb-tag">${sbi('up',15)} Lampiran II</span><h4>Dapat dilampaui</h4><p>Dapat dilampaui saat pelaksanaan anggaran dengan mempertimbangkan <b>harga pasar</b> serta prinsip <b>ekonomis, efisien, dan efektif</b>, didukung bukti kewajaran.</p></div></div>
${sbFacts([['58','jenis SBM dikaji untuk TA 2027'],['55','jenis tidak berubah besarannya'],['3','jenis naik tarif (121 rincian)']])}
<p class="sb-note">${icon('help',16)} <span>Kenaikan TA 2027 hanya pada honorarium satpam, pengemudi, dan pramubakti (+4,94%), bahan makanan narapidana (+5,30%), dan konsumsi tahanan/deteni/ABK nonjustisia (+1,75%). Satuan biaya di luar SBM dapat memakai harga pasar atau satuan harga instansi teknis. Honorarium atau fasilitas tambahan di luar SBM (Satuan Biaya Masukan Lainnya) memerlukan persetujuan Menteri Keuangan.</span></p>
<p class="sb-when">${icon('calendar',16)} Digunakan untuk penyusunan RKA mulai <b>TA 2027</b>. Rincian besaran ada di KMK 296/2026.</p></article>

<article class="sb-card sb-sbk" id="sb-sbk">${sbHead(k,'02')}
<p class="sb-lead"><b>SBK</b> adalah <b>indeks biaya</b> yang ditetapkan untuk menghasilkan <b>1 (satu) volume keluaran</b>. Jika SBM menjawab "berapa harga tiap bahannya", SBK menjawab "berapa biaya total untuk menghasilkan satu output", misalnya satu layanan audit internal atau satu peraturan menteri.</p>
<div class="sb-split"><div class="sb-box"><span class="sb-tag">${sbi('users',15)} Lampiran I</span><h4>SBK Umum (SBKU)</h4><p>Berlaku untuk lebih dari satu atau seluruh K/L. Contoh: Layanan Perencanaan dan Penganggaran, Layanan Pelatihan, Layanan Audit Internal, Peraturan Menteri/Pimpinan Lembaga, dan Sosialisasi.</p></div><div class="sb-box"><span class="sb-tag">${sbi('target',15)} Lampiran II</span><h4>SBK Khusus (SBKK)</h4><p>Berlaku untuk satu K/L, sesuai keluaran teknis yang menjadi tugas dan fungsinya. Usulan berasal dari Rincian Output (RO) yang berulang.</p></div></div>
<h3 class="sb-sub">Manfaat SBK</h3>
<ul class="sb-list">${['Memperbaiki kualitas perencanaan.','Mempercepat penyusunan dan penelaahan RKA-K/L.','Memudahkan monitoring dan evaluasi pencapaian keluaran.'].map(x=>`<li>${sbi('check',16)}${x}</li>`).join('')}</ul>
<h3 class="sb-sub">Kriteria keluaran yang dapat menjadi SBK Khusus</h3>
<ol class="sb-steps"><li><b>Berulang</b><span>pada tahun anggaran berikutnya atau antar-K/L</span></li><li><b>Jenis dan satuan jelas</b><span>barang/jasa yang dapat diukur secara kuantitas</span></li><li><b>Komponen/tahapan jelas</b><span>mencerminkan perencanaan, pengorganisasian, pelaksanaan, dan pengendalian</span></li></ol>
${sbFacts([['Batas tertinggi','tidak dapat dilampaui'],['23','jenis SBK Umum'],['3.231','RO diusulkan K/L menjadi SBKK 2026']])}
<p class="sb-note">${icon('help',16)} <span>Bila K/L membutuhkan besaran di atas SBK, K/L mengajukan permintaan pelampauan kepada Menteri Keuangan. Dirjen Anggaran atas nama Menteri Keuangan dapat menyetujuinya dengan pertimbangan harga pasar, prinsip ekonomis, efisien, dan efektif, dan/atau perubahan tahapan.</span></p>
<p class="sb-when">${icon('calendar',16)} Digunakan untuk penyusunan RKA-K/L mulai <b>TA 2026</b> dan berlaku terus-menerus (<i>long lasting</i>). Rincian indeks ada di KMK 57/2026.</p></article>

<article class="sb-card sb-ssb" id="sb-ssb">${sbHead(s,'03')}
<p class="sb-lead"><b>SSB</b> adalah batasan besaran atau persentase <b>komposisi biaya dalam 1 (satu) keluaran</b>. SSB menjaga agar sebagian besar anggaran benar-benar dipakai untuk menghasilkan output, bukan untuk biaya penunjangnya.</p>
<div class="sb-split"><div class="sb-box"><span class="sb-tag">${sbi('target',15)} Biaya utama</span><h4>Berpengaruh langsung pada keluaran</h4><p>Komponen 001 (gaji dan tunjangan), 002 (operasional dan pemeliharaan kantor), 003 (dukungan operasional hankam), 004 (dukungan operasional pendidikan), 005 (dukungan tugas dan fungsi unit), dan komponen lain yang berpengaruh langsung.</p></div><div class="sb-box"><span class="sb-tag">${sbi('pie',15)} Biaya pendukung</span><h4>Dibatasi persentasenya</h4><p>Honorarium tim kegiatan, konsumsi rapat dalam kantor, kegiatan seremonial, percetakan, souvenir, ATK kegiatan, serta komponen yang tidak berpengaruh langsung terhadap keluaran.</p></div></div>
<h3 class="sb-sub">Batas tertinggi biaya pendukung per Grup KRO</h3>
<div class="sb-bars">${[['Kerangka Regulasi',7],['Kerangka Pelayanan Umum',9],['Kerangka Investasi Fisik',6],['Kerangka Investasi SDM dan Sosial Ekonomi',9],['Administrasi Pemerintahan Internal K/L',9],['Administrasi Pemerintahan antar-K/L dan Pusat-Daerah',9]].map(([n,v])=>`<div class="sb-bar"><span>${n}</span><div><i style="width:${v/10*100}%"></i></div><b>${v}%</b></div>`).join('')}</div>
<p class="sb-formula">${sbi('pie',16)} Persentase SSB = (biaya pendukung) ÷ (total biaya RO). Komponen utama tidak dihitung sebagai biaya pendukung.</p>
<h3 class="sb-sub">Perjalanan pengaturan SSB</h3>
<ol class="sb-timeline"><li><b>2016</b><span>PMK 195/PMK.02/2014: fondasi awal; biaya pendukung maksimal 45%, hanya untuk output jasa layanan nonregulasi.</span></li><li><b>2021</b><span>PMK 140/PMK.02/2021: cakupan output diperluas; batas biaya pendukung 6–9% per jenis output.</span></li><li><b>2025</b><span>PMK 79/2025: berlaku untuk seluruh K/L, seluruh RO, dan seluruh sumber dana; batas berdasarkan 6 Grup KRO.</span></li></ol>
<p class="sb-note">${icon('help',16)} <span>Bersifat batas tertinggi dalam perencanaan dan pelaksanaan. K/L dapat meminta pelampauan kepada Menteri Keuangan untuk kegiatan prioritas Presiden, program/kegiatan/proyek prioritas K/L, atau kontrak tahun jamak. Persetujuan diberikan Dirjen Anggaran atas nama Menteri Keuangan.</span></p></article>

<section class="sb-compare"><h2>Sekilas perbandingan</h2><div class="sb-table"><table><thead><tr><th>Aspek</th><th class="c-sbm">SBM</th><th class="c-sbk">SBK</th><th class="c-ssb">SSB</th></tr></thead><tbody>
<tr><th>Yang diatur</th><td>Harga satuan masukan</td><td>Biaya per satu volume keluaran</td><td>Komposisi biaya dalam satu keluaran</td></tr>
<tr><th>Bentuk</th><td>Satuan biaya (Rp)</td><td>Indeks biaya (Rp per output)</td><td>Persentase biaya pendukung</td></tr>
<tr><th>Sifat</th><td>Batas tertinggi atau dapat dilampaui</td><td>Batas tertinggi; pelampauan dengan persetujuan</td><td>Batas tertinggi; pelampauan dengan persetujuan</td></tr>
<tr><th>Dasar hukum</th><td>PMK 54/2026, KMK 296/2026</td><td>PMK 3/2026, KMK 57/2026</td><td>PMK 79/2025</td></tr>
<tr><th>Mulai digunakan</th><td>RKA TA 2027</td><td>RKA-K/L TA 2026</td><td>Seluruh K/L dan sumber dana</td></tr>
</tbody></table></div><p class="sb-when">${icon('book',16)} Penerapan ketiganya berpedoman pada PMK 62/2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan, sebagaimana diubah dengan PMK 107/2024 dan PMK 41/2026. Naskah lengkapnya ada di menu <button class="text-button" data-page="pustaka">Pustaka ${icon('arrow',14)}</button></p></section>`;};
// Dashboard: peta rekap SBM/SBK/SSB dari public/data/rekap.json (scripts/buat_rekap.py).
let rekapData=null,rekapError='';
async function loadRekap(){if(rekapData||rekapError)return;try{const r=await fetch('/data/rekap.json',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error();rekapData=await r.json();}catch(e){rekapError='Rekap belum dapat dimuat. Coba muat ulang halaman.';}if(state.page==='dashboard')render();}
const KLASTER_IKON={'Honorarium':'coin','Fasilitas':'star','Perjalanan Dinas':'plane','Pemeliharaan':'tool','Barang dan Jasa':'box','Bantuan':'gift'};
const num=(n)=>Number(n).toLocaleString('id-ID');
const mapHero=(k,img,kode,nama,stats,law)=>`<a class="map-hero map-${k}" href="#map-${k}"><img src="/icons/${img}" alt=""/><div><small>${kode}</small><b>${nama}</b><div class="map-hero-stats">${stats.map(([v,l])=>`<span><strong>${v}</strong>${l}</span>`).join('')}</div><em>${law}</em></div></a>`;
function dashboard(){
if(rekapError)return `<div class="error-box">${escapeHTML(rekapError)}</div>`;
if(!rekapData){loadRekap();return '<div class="loading">Memuat rekap standar biaya...</div>';}
const {sbm,ssb,sbk}=rekapData;
const bt=sbm.klaster.reduce((a,c)=>a+c.batas_tertinggi.length,0),dd=sbm.klaster.reduce((a,c)=>a+c.dapat_dilampaui.length,0);
const sbkkTotal=sbk.sbkk.reduce((a,x)=>a+x.jumlah,0),roSbku=sbk.sbku.reduce((a,x)=>a+x.ro,0),maxKl=sbk.sbkk[0].jumlah,minPct=Math.min(...ssb.grup_kro.map(g=>g.persen)),maxPct=Math.max(...ssb.grup_kro.map(g=>g.persen));
const top=sbk.sbkk.slice(0,12);
return `<section class="page-head">${pageIcon()}<span class="small-label">RINGKASAN INFORMASI</span><h1>Dashboard Standar Biaya</h1><p>Peta rekap ketiga jenis standar biaya: berapa klaster, jenis, grup, dan K/L yang diatur oleh masing-masing regulasi.</p></section>
<section class="map-heroes">${mapHero('sbm','sbm.svg','SBM','Standar Biaya Masukan',[[sbm.klaster.length,'klaster'],[sbm.jumlah_jenis,'jenis']],'PMK 54/2026 · KMK 296/2026')}${mapHero('sbk','sbk.svg','SBK','Standar Biaya Keluaran',[[sbk.sbku.length,'SBKU'],[num(sbkkTotal),'SBKK']],'PMK 3/2026 · KMK 57/2026')}${mapHero('ssb','ssb.svg','SSB','Standar Struktur Biaya',[[ssb.grup_kro.length,'Grup KRO'],[minPct+'–'+maxPct+'%','batas']],'PMK 79/2025')}</section>

<section class="map-block map-sbm" id="map-sbm"><header class="map-head"><span class="map-icon">${sbi('coin',26)}</span><div><h2>SBM: ${sbm.klaster.length} klaster, ${sbm.jumlah_jenis} jenis</h2><p>${bt} jenis bersifat <b>batas tertinggi</b> (Lampiran I) dan ${dd} jenis <b>dapat dilampaui</b> (Lampiran II).</p></div></header>
<div class="map-flow"><div class="map-root">SBM<small>${sbm.jumlah_jenis} jenis</small></div><div class="map-branches">${sbm.klaster.map(c=>{const n=c.batas_tertinggi.length+c.dapat_dilampaui.length;return `<details class="klaster"><summary><span class="k-icon">${sbi(KLASTER_IKON[c.nama]||'box',22)}</span><span class="k-name">${escapeHTML(c.nama)}</span><span class="k-count">${n}<small>jenis</small></span><span class="k-bar" title="${c.batas_tertinggi.length} batas tertinggi, ${c.dapat_dilampaui.length} dapat dilampaui"><i style="width:${n?c.batas_tertinggi.length/n*100:0}%"></i></span><span class="k-meta">${c.batas_tertinggi.length} batas tertinggi · ${c.dapat_dilampaui.length} dapat dilampaui · ${num(c.rincian_terbaca)} rincian besaran</span></summary><ul>${c.batas_tertinggi.map(x=>`<li><i class="tag-bt">BT</i>${escapeHTML(x)}</li>`).join('')}${c.dapat_dilampaui.map(x=>`<li><i class="tag-dd">DD</i>${escapeHTML(x)}</li>`).join('')}</ul></details>`;}).join('')}</div></div>
<p class="map-note">${icon('help',15)} Klik klaster untuk melihat daftar jenisnya. BT = batas tertinggi, DD = dapat dilampaui. "Rincian besaran" adalah jumlah baris tarif KMK 296/2026 yang terbaca otomatis di menu Indeks KMK (belum diverifikasi).</p></section>

<section class="map-block map-sbk" id="map-sbk"><header class="map-head"><span class="map-icon">${sbi('target',26)}</span><div><h2>SBK: ${sbk.sbku.length} SBKU dan ${num(sbkkTotal)} SBKK di ${sbk.sbkk.length} K/L</h2><p><b>SBK Umum</b> berlaku untuk lebih dari satu atau seluruh K/L. <b>SBK Khusus</b> berlaku untuk satu K/L.</p></div></header>
<div class="sbk-split"><div class="sbk-col"><h3>${sbi('users',18)} SBK Umum <span>${sbk.sbku.length} jenis · ${roSbku} rincian RO</span></h3><ol class="sbku-list">${sbk.sbku.map(x=>`<li><b>${x.no}</b><span>${escapeHTML(x.nama.replace(/^SBK /,''))}</span>${x.ro>1?`<em>${x.ro} RO</em>`:''}</li>`).join('')}</ol></div>
<div class="sbk-col"><h3>${sbi('target',18)} SBK Khusus <span>${num(sbkkTotal)} keluaran · ${sbk.sbkk.length} K/L</span></h3><div class="kl-bars">${top.map(x=>`<div class="kl-bar"><span title="${escapeHTML(x.nama)}"><b>${x.kode}</b> ${escapeHTML(x.nama)}</span><div><i style="width:${x.jumlah/maxKl*100}%"></i></div><strong>${num(x.jumlah)}</strong></div>`).join('')}</div><details class="kl-all"><summary>Lihat semua ${sbk.sbkk.length} K/L</summary><div class="kl-table"><table><thead><tr><th>Kode BA</th><th>Kementerian/Lembaga</th><th>SBKK</th></tr></thead><tbody>${sbk.sbkk.map(x=>`<tr><td>${x.kode}</td><td>${escapeHTML(x.nama)}</td><td>${num(x.jumlah)}</td></tr>`).join('')}</tbody></table></div></details></div></div>
<p class="map-note">${icon('help',15)} Jumlah SBKK dihitung dari Lampiran II PMK 3/2026 dan sama dengan Lampiran II KMK 57/2026.</p></section>

<section class="map-block map-ssb" id="map-ssb"><header class="map-head"><span class="map-icon">${sbi('pie',26)}</span><div><h2>SSB: ${ssb.grup_kro.length} Grup KRO</h2><p>Batas tertinggi biaya pendukung terhadap total biaya RO, berlaku untuk seluruh K/L, RO, dan sumber dana.</p></div></header>
<div class="kro-grid">${ssb.grup_kro.map((g,i)=>`<article class="kro"><div class="kro-ring" style="--p:${g.persen*10}"><span>${g.persen}%</span></div><div><small>Grup KRO ${i+1}</small><b>${escapeHTML(g.nama[0].toUpperCase()+g.nama.slice(1))}</b></div></article>`).join('')}</div>
<p class="map-note">${icon('help',15)} Lingkaran menunjukkan besaran batas pada skala 0–10%.</p></section>

<section class="map-block map-db"><header class="map-head"><span class="map-icon">${icon('chart',24)}</span><div><h2>Data di database portal</h2><p>Ringkasan publikasi terakhir dari Google Sheets.</p></div></header><section class="stats inpage">${stat(state.summary?.itemCount??'—','Total Item','book')}${stat(state.summary?.regulationCount??'—','Total Regulasi','file')}${stat(state.summary?.documentCount??'—','Total Dokumen','shield')}</section><section class="chart-panel"><h2>Distribusi Jenis Standar Biaya</h2>${(state.summary?.byType||[]).length?(state.summary.byType.map(x=>`<div class="bar-row"><span>${escapeHTML(x.name)}</span><div class="bar-track"><div style="width:${Math.round(100*Number(x.value)/(Math.max(1,...state.summary.byType.map(i=>Number(i.value)||0))))}%"></div></div><strong>${escapeHTML(x.value)}</strong></div>`).join('')):'<p>Belum ada ringkasan distribusi yang dipublikasikan.</p>'}</section></section>`;}

let biayaCandidates=null;
async function loadCandidates(){if(!biayaCandidates){const resp=await fetch('/data/kandidat-indeks.json',{credentials:'same-origin',cache:'no-store'});if(!resp.ok)throw Error('File indeks belum tersedia');biayaCandidates=await resp.json();}return biayaCandidates;}
// SBM per 6 klaster sesuai judul bagian KMK 296/2026, SBK per K/L (kolom dari scripts/tambah_filter_indeks.py).
const SBM_KLASTER=['Honorarium','Fasilitas','Perjalanan Dinas','Pemeliharaan','Barang dan Jasa','Bantuan'];
const groupOf=(r)=>r.jenis==='SBM'?r.klaster:r.kl;
async function updateGroupFilter(){const kind=document.querySelector('#biaya-kind').value;const select=document.querySelector('#biaya-group');select.hidden=!kind;select.innerHTML='';if(!kind)return;select.innerHTML=`<option value="">Memuat ${kind==='SBM'?'klaster':'K/L'}...</option>`;try{await loadCandidates();}catch(e){select.hidden=true;return;}const count={};for(const r of biayaCandidates.rows)if(r.jenis===kind){const g=groupOf(r);if(g)count[g]=(count[g]||0)+1;}const names=kind==='SBM'?SBM_KLASTER:Object.keys(count).sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));select.innerHTML=`<option value="">${kind==='SBM'?'Semua klaster (6)':'Semua K/L ('+names.length+')'}</option>`+names.map(n=>`<option value="${escapeHTML(n)}">${escapeHTML(n)} (${count[n]||0})</option>`).join('');}
function indeksKmk(){return `<section class="page-head">${pageIcon()}<span class="small-label">EKSTRAKSI TERSTRUKTUR DOKUMEN</span><h1>Indeks Besaran SBM & SBK</h1><p>Cari uraian, nominal rupiah, satuan, kode SBK, atau nomor regulasi dari PDF sumber.</p></section><div class="reg-advisory"><b>PENTING:</b> Data di halaman ini dibaca otomatis dari PDF KMK dan <b>belum diperiksa</b>. Angka bisa keliru. Selalu klik "Periksa halaman sumber" dan gunakan angka di PDF resmi untuk perencanaan anggaran.</div><form id="biaya-query-form" class="toolbar"><label class="filter-search">${icon('search',20)}<input id="biaya-q" placeholder="Cari: honorarium, uang makan, layanan audit, 630000..." aria-label="Cari kandidat besaran biaya" /></label><select id="biaya-kind" aria-label="Jenis standar biaya"><option value="">Semua jenis</option><option value="SBM">SBM (KMK 296)</option><option value="SBK">SBK (KMK 57)</option></select><select id="biaya-group" aria-label="Filter klaster SBM atau K/L" hidden></select><button type="submit" class="secondary">Cari indeks</button></form><div class="result-note">Pilih SBM untuk filter per klaster, atau SBK untuk filter per K/L. Hasil tampil maksimum 100 baris. Klik sumber untuk mengecek angka pada halaman PDF.</div><div id="biaya-result"><p class="empty">Masukkan kata kunci untuk melihat kandidat data.</p></div>`;}
async function lookupBiaya(e){e.preventDefault();const target=document.querySelector('#biaya-result');const q=document.querySelector('#biaya-q').value.trim().toLowerCase();const kind=document.querySelector('#biaya-kind').value;const group=document.querySelector('#biaya-group').value;if(q.length<2&&!group){target.innerHTML='<p class="empty">Masukkan paling sedikit dua karakter, atau pilih klaster/K/L.</p>';return;}target.textContent='Memuat indeks terstruktur...';try{await loadCandidates();const results=biayaCandidates.rows.filter(r=>(!kind||r.jenis===kind)&&(!group||groupOf(r)===group)&&[r.uraian,r.kode_item,r.kode_program,r.satuan,r.besaran_rupiah,r.regulasi,r.halaman_pdf].join(' ').toLowerCase().includes(q));const found=results.slice(0,100);target.innerHTML=`<p class="result-note">Ditemukan ${results.length} kandidat. Maksimum 100 ditampilkan; semuanya belum diverifikasi.</p>`+(found.length?`<div class="kmk-index-list">${found.map(r=>`<article class="kmk-index-card"><div class="entry-head">${badge(r.jenis)} ${badge(r.regulasi)} <span class="verification pending">PERLU REVIEW</span></div><h3>${escapeHTML(r.uraian)}</h3>${groupOf(r)?`<div class="group-tag">${icon(r.jenis==='SBK'?'shield':'layers',14)} ${escapeHTML(groupOf(r))}</div>`:''}<div><strong>Rp ${Number(r.besaran_rupiah).toLocaleString('id-ID')}</strong> ${escapeHTML(r.volume?r.volume+' ':'')}${escapeHTML(r.satuan)}</div><p>${escapeHTML(r.kode_program||r.kode_item||'')} · Lampiran ${escapeHTML(r.lampiran)} · Halaman PDF ${r.halaman_pdf}</p><a href="${escapeHTML(r.sumber_pdf)}#page=${r.halaman_pdf}" target="_blank" rel="noopener noreferrer">Periksa halaman sumber ↗</a></article>`).join('')}</div>`:'<p class="empty">Tidak ada kandidat cocok. Gunakan pencarian teks PDF pada menu Regulasi.</p>');}catch(e){target.innerHTML='<p class="empty">Indeks tidak tersedia. Pastikan file /data/kandidat-indeks.json ikut terunggah.</p>';}}

// Pustaka: file disimpan di Google Drive (kolom drive_file_id pada sheet DOKUMEN).
// PUSTAKA_FILES: file di folder Google Drive pengelola; tambah baris baru untuk file berikutnya.
const PUSTAKA_FILES=[
 {id: "PUS-01", judul: "Sosialisasi PMK 54/2026 dan KMK 296/2026 tentang SBM", kategori: "Bahan Tayang", tahun: 2026, deskripsi: "Kerangka SBM dalam PMK 54/2026 dan rincian besaran KMK 296/2026 untuk penyusunan RKA-K/L TA 2027.", drive_file_id: "1zK4WcyQbEMMAOgnS5Er0v7ZbfJpMTnK4"},
 {id: "PUS-02", judul: "Sosialisasi Standar Biaya Keluaran Umum (SBKU)", kategori: "Bahan Tayang", tahun: 2026, deskripsi: "Standardisasi kode RO generik dan indeks SBKU, termasuk contoh Layanan Audit Internal.", drive_file_id: "1CM57rMVw2yWax4W84e2EbTm-C9chfUWy"},
 {id: "PUS-03", judul: "Penyusunan Standar Biaya Keluaran", kategori: "Bahan Tayang", tahun: 2026, deskripsi: "Peran standar biaya dalam penganggaran berbasis kinerja serta tahapan penyusunan SBK.", drive_file_id: "1nFeHlMwf9h32EyZxIsMfttSe2k8cg0hb"},
 {id: "PUS-04", judul: "Sosialisasi PMK 79/2025 tentang Standar Struktur Biaya", kategori: "Bahan Tayang", tahun: 2025, deskripsi: "Perkembangan dan pokok pengaturan SSB, termasuk batas biaya pendukung.", drive_file_id: "1z69YaenKlgfq0E_P8z9s-RYNfRfg-Glt"},
 {id: "PUS-05", judul: "PMK 54/2026 tentang Standar Biaya Masukan", kategori: "Regulasi PDF", tahun: 2026, deskripsi: "Naskah peraturan SBM untuk penyusunan RKA mulai TA 2027.", drive_file_id: "1xQaKBiQRrJ1Fv48_J4DZAbCxlGM6eaPl"},
 {id: "PUS-06", judul: "KMK 296/2026 tentang Rincian Besaran SBM", kategori: "Regulasi PDF", tahun: 2026, deskripsi: "Lampiran I batas tertinggi dan Lampiran II dapat dilampaui, berlaku TA 2027.", drive_file_id: "1bzaTcVCVTUz9R141OREq3up9Fsj-7zkI"},
 {id: "PUS-07", judul: "PMK 3/2026 tentang Standar Biaya Keluaran", kategori: "Regulasi PDF", tahun: 2026, deskripsi: "Kategori SBK umum dan khusus untuk RKA-K/L mulai 2026.", drive_file_id: "1ZCEw2NcDuRUW6jbro4dz4ZeckN-Vj7-Z"},
 {id: "PUS-08", judul: "KMK 57/2026 tentang Rincian Indeks SBK", kategori: "Regulasi PDF", tahun: 2026, deskripsi: "Lampiran I SBK umum dan Lampiran II SBK khusus.", drive_file_id: "1sGvIUA3X5EfpCHkcBDRILIfZ5gqqzy49"},
 {id: "PUS-09", judul: "PMK 79/2025 tentang Standar Struktur Biaya", kategori: "Regulasi PDF", tahun: 2025, deskripsi: "Naskah peraturan SSB dalam penganggaran K/L.", drive_file_id: "1U211OFHed2Qjx_Qh7_-hlakd43f3ITIF"},
 {id: "PUS-10", judul: "PMK 62/2023 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan", kategori: "Regulasi PDF", tahun: 2023, deskripsi: "Pedoman penerapan standar biaya dalam perencanaan dan pelaksanaan anggaran.", drive_file_id: "1qfvZqpBxU8StRx8VkBeV89FoHsE-0Xvc"},
 {id: "PUS-11", judul: "PMK 107/2024 tentang Perubahan atas PMK 62/2023", kategori: "Regulasi PDF", tahun: 2024, deskripsi: "Perubahan pertama PMK 62/2023 untuk menyederhanakan proses bisnis pengelolaan anggaran.", drive_file_id: "1_0MY2IY9K72WHiH6ejrOc6Q9y0UCrhU3"},
 {id: "PUS-12", judul: "PMK 41/2026 tentang Perubahan Kedua atas PMK 62/2023", kategori: "Regulasi PDF", tahun: 2026, deskripsi: "Perubahan kedua PMK 62/2023, termasuk ketentuan Satuan Biaya Masukan Lainnya (Pasal 49).", drive_file_id: "1Vhklm5v3iX4_UdaxCOsQGafqe0TOqO-a"}
];
const driveId=(x)=>typeof x?.drive_file_id==='string'&&/^[\w-]{10,150}$/.test(x.drive_file_id)?x.drive_file_id:'';
const fileKind=(x)=>{const t=[x.kategori,x.judul].join(' ').toLowerCase();return /ppt|tayang|paparan|presentasi|slide|sosialisasi/.test(t)?['ppt','Bahan Tayang']:/pdf|regulasi|pmk|kmk|peraturan/.test(t)?['pdf','Dokumen PDF']:['doc','Dokumen'];};
const fileBadge=(kind)=>`<span class="file-icon file-${kind}" aria-hidden="true">${kind==='ppt'?'<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="4" width="20" height="13" rx="2"/><path d="M12 17v4M8 21h8M9 8v5M9 8h3a2 2 0 0 1 0 4H9"/></svg>':icon('file',26)}</span>`;
const docCard=(x)=>{const id=driveId(x),[kind,label]=fileKind(x);return `<article class="doc-card doc-${kind}">${fileBadge(kind)}<div class="doc-body"><div class="entry-head"><span class="pill">${escapeHTML(x.kategori||label)}</span><small>${escapeHTML(x.tahun||'')}</small></div><h3>${escapeHTML(x.judul||'Tanpa judul')}</h3><p>${escapeHTML(x.deskripsi||'')}</p><div class="doc-actions">${id?`<button class="secondary" data-preview="${escapeHTML(id)}" data-title="${escapeHTML(x.judul||'')}">${icon('eye',16)} Pratinjau</button><a class="ghost-button" href="https://drive.google.com/file/d/${id}/view" target="_blank" rel="noopener noreferrer">Buka di Google Drive ↗</a>`:'<span class="result-note">File belum ditautkan.</span>'}</div></div></article>`;};
const library=()=>{const all=[...PUSTAKA_FILES,...state.docs.filter(x=>!PUSTAKA_FILES.some(f=>f.drive_file_id===x.drive_file_id))];const kinds=[['','Semua'],['ppt','Bahan Tayang'],['pdf','PDF'],['doc','Dokumen lain']];const docs=all.filter(x=>(!state.docKind||fileKind(x)[0]===state.docKind)&&(!state.docSearch||[x.judul,x.kategori,x.deskripsi,x.tahun].join(' ').toLowerCase().includes(state.docSearch.toLowerCase())));return `<section class="page-head">${pageIcon()}<span class="small-label">PUSTAKA</span><h1>Pustaka Standar Biaya</h1><p>Bahan tayang dan dokumen referensi. File tersimpan di Google Drive dan dapat dipratinjau langsung.</p></section><div class="toolbar"><label class="filter-search">${icon('search',20)}<input id="doc-search" placeholder="Cari judul, kategori, tahun..." value="${escapeHTML(state.docSearch)}" /></label></div><div class="chips">${kinds.map(([k,l])=>`<button class="chip ${state.docKind===k?'active':''}" data-dockind="${k}">${l}<span>${k?all.filter(x=>fileKind(x)[0]===k).length:all.length}</span></button>`).join('')}</div><div class="doc-list">${docs.length?docs.map(docCard).join(''):'<div class="empty">Belum ada dokumen yang cocok.</div>'}</div>`;};
function previewDoc(id,title){const element=document.createElement('dialog');element.className='detail-dialog preview-dialog';element.innerHTML=`<div class="preview-head"><h2>${escapeHTML(title)}</h2><a href="https://drive.google.com/file/d/${id}/view" target="_blank" rel="noopener noreferrer">Buka di Drive ↗</a><button class="close-dialog" aria-label="Tutup">×</button></div><div class="preview-frame"><iframe src="https://drive.google.com/file/d/${id}/preview" title="Pratinjau ${escapeHTML(title)}" allow="autoplay; fullscreen" allowfullscreen loading="lazy"></iframe></div><p class="result-note">Jika pratinjau kosong, pastikan file dibagikan "Siapa saja yang memiliki link".</p>`;document.body.append(element);element.showModal();const close=()=>{element.close();element.remove();};element.querySelector('.close-dialog').onclick=close;element.onclick=e=>{if(e.target===element)close();};}

const content=()=>state.page==='beranda'?home():state.page==='mengenal'?intro():state.page==='kamus'?catalog():state.page==='regulasi'?regulationCatalog():state.page==='dashboard'?dashboard():state.page==='pustaka'?library():state.page==='indeks'?indeksKmk():faq();
function render(){root.innerHTML=`<header class="topbar"><div class="container header-wrap"><button class="brand" data-page="beranda"><img src="/icons/portal-logo.svg" alt="Logo Standar Biaya"/><span><b class="wordmark"><span>Standar</span> <span>Biaya</span></b><small>Pusat Informasi Standar Biaya</small></span></button><nav id="nav">${menu()}</nav><div class="header-actions"><form action="/logout" method="post" id="logout-form"><button class="logout" type="submit">${icon('logout',17)}<span>Keluar</span></button></form><button id="mobile-menu" aria-label="Buka menu">${icon('menu',24)}</button></div></div></header><main class="container">${state.error?`<div class="error-box">${escapeHTML(state.error)} <button id="reload">Coba lagi</button></div>`:''}${state.loading?'<div class="loading">Memuat informasi portal...</div>':content()}</main><footer class="footer"><div class="container foot-inner"><div class="foot-brand"><img src="/icons/portal-logo.svg" alt="Logo Standar Biaya"/><div><b class="wordmark"><span>Standar</span> <span>Biaya</span></b><p>Pusat informasi dan penelusuran standar biaya.</p></div></div><span>Periksa dasar hukum sebelum menggunakan suatu besaran.</span></div></footer>`;bind();}
function go(page){state.page=page;state.selected=null;window.scrollTo({top:0,behavior:'smooth'});render();}
async function detail(id){const res=await fetch('/api/items/'+encodeURIComponent(id));if(!res.ok)return;const x=(await res.json()).data;const element=document.createElement('dialog');element.className='detail-dialog';element.innerHTML=`<button class="close-dialog" aria-label="Tutup">×</button>${badge(x.item?.jenis||'Item')}<h2>${escapeHTML(x.item?.nama)}</h2><p>${escapeHTML(x.item?.definisi||'')}</p><p><strong>Kelompok:</strong> ${escapeHTML(x.item?.kelompok)} &nbsp; <strong>Satuan:</strong> ${escapeHTML(x.item?.satuan)}</p><h3>Besaran Biaya</h3>${(x.rates||[]).length?'<div class="rate-list">'+x.rates.map(r=>`<p><b>${escapeHTML(r.tahun)}</b> · ${escapeHTML(r.wilayah)} · ${escapeHTML(r.kategori)}<br><strong>${r.mata_uang==='IDR'?'Rp ':''}${Number(r.besaran).toLocaleString('id-ID')}${r.mata_uang==='PCT'?'%':''}</strong></p>`).join('')+'</div>':'<p>Besaran tidak tersedia.</p>'}<h3>Referensi regulasi: ${(x.regulations||[]).length}</h3>`;document.body.append(element);element.showModal();element.querySelector('.close-dialog').onclick=()=>{element.close();element.remove();};element.onclick=e=>{if(e.target===element){element.close();element.remove();}};}
function bind(){document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>go(x.dataset.page));document.querySelectorAll('[data-search]').forEach(x=>x.onclick=()=>{state.search=x.dataset.search;state.jenis='';state.kelompok='';go('kamus');});document.querySelectorAll('[data-kind]').forEach(x=>x.onclick=()=>{state.jenis=x.dataset.kind;state.kelompok='';state.search='';go('kamus');});document.querySelectorAll('[data-preview]').forEach(x=>x.onclick=()=>previewDoc(x.dataset.preview,x.dataset.title));document.querySelectorAll('[data-dockind]').forEach(x=>x.onclick=()=>{state.docKind=x.dataset.dockind;render();});document.querySelector('#doc-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;state.docSearch=e.target.value;render();const node=document.querySelector('#doc-search');node.focus();node.setSelectionRange(pos,pos);});document.querySelectorAll('[data-detail]').forEach(x=>x.onclick=()=>detail(x.dataset.detail));document.querySelector('#hero-search')?.addEventListener('submit',e=>{e.preventDefault();state.search=new FormData(e.target).get('q')?.toString()||'';state.jenis='';state.kelompok='';go('kamus');});document.querySelector('#catalog-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;state.search=e.target.value;render();const node=document.querySelector('#catalog-search');node.focus();node.setSelectionRange(pos,pos);});document.querySelector('#catalog-kind')?.addEventListener('change',e=>{state.jenis=e.target.value;state.kelompok='';render();});document.querySelectorAll('[data-kamustab]').forEach(x=>x.onclick=()=>{state.kamusTab=x.dataset.kamustab;render();});document.querySelectorAll('[data-kelompok]').forEach(x=>x.onclick=()=>{state.kelompok=x.dataset.kelompok;render();});document.querySelector('#kmk-search-form')?.addEventListener('submit',kmkLookup);document.querySelector('#biaya-query-form')?.addEventListener('submit',lookupBiaya);document.querySelector('#biaya-kind')?.addEventListener('change',updateGroupFilter);document.querySelector('#biaya-group')?.addEventListener('change',()=>document.querySelector('#biaya-query-form').requestSubmit());document.querySelector('#mobile-menu')?.addEventListener('click',()=>document.querySelector('#nav').classList.toggle('open'));document.querySelector('#reload')?.addEventListener('click',load);}
load();
